  <td><?php if ($p['status'] === 'draft'): ?><form method="post" action="/admin/proposals/<?= (int)$p['id'] ?>/send"><?= App\Csrf::field() ?><button class="btn btn-ghost btn-sm">Send</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
